//! F10 (Task 9): HAR 1.2 export/import + mitmproxy `.flows` import.
//!
//! Every test drives the real commands through a `Registry` + `CommandHost`, the
//! way a frontend does. AC-F10.2 is the HAR 1.2 export/import round-trip of
//! url/status; the mitmproxy case imports a genuine `.flows` blob (generated by
//! mitmproxy 12.2.2, see `tests/fixtures/sample.flows`). Import stays passive: the
//! counting client's egress counter must never move.

use std::collections::BTreeMap;
use std::net::{Ipv4Addr, SocketAddr, SocketAddrV4};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::SystemTime;

use aitm_core::{
    Body, CommandHost, ConnInfo, Flow, FlowId, FlowMeta, FlowStore, HeaderMap, HttpFlow,
    HttpRequest, HttpResponse, HttpVersion, InterceptState, MemFlowStore, Params, ProxyClient,
    Registry, StdGuard, Value, WsDir, WsFlow, WsMessage, WsOpcode,
};
use aitm_plugin_sessionio::har::Har;
use aitm_plugin_sessionio::SessionIoPlugin;
use futures::future::BoxFuture;

/// A `ProxyClient` that counts and refuses every `send`, so a test can prove
/// import touched the store and nothing else.
#[derive(Default)]
struct CountingClient {
    sends: AtomicUsize,
}

impl ProxyClient for CountingClient {
    fn send(&self, _req: HttpRequest) -> BoxFuture<'_, anyhow::Result<HttpFlow>> {
        self.sends.fetch_add(1, Ordering::SeqCst);
        Box::pin(async { anyhow::bail!("stub client: import must not send upstream") })
    }
}

fn registry() -> Registry {
    let mut reg = Registry::new();
    reg.add_plugin(Box::new(SessionIoPlugin::new(false)));
    reg
}

/// A GET flow with a known scheme/authority/path and status, so the HAR entry's
/// `request.url` and `response.status` have exact expected values.
fn seeded_flow() -> Flow {
    let addr = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 8080));
    let mut req_headers = HeaderMap::new();
    req_headers.set("Host", "api.example.test");
    req_headers.set("Accept", "application/json");
    let mut resp_headers = HeaderMap::new();
    resp_headers.set("Content-Type", "application/json");
    Flow::Http(HttpFlow {
        id: FlowId::new(),
        request: HttpRequest {
            method: "GET".into(),
            scheme: "https".into(),
            authority: "api.example.test".into(),
            path: "/v1/items?page=2".into(),
            version: HttpVersion::Http11,
            headers: req_headers,
            body: Body::Empty,
            timestamp: SystemTime::now(),
        },
        response: Some(HttpResponse {
            status: 201,
            version: HttpVersion::Http11,
            headers: resp_headers,
            trailers: HeaderMap::new(),
            body: Body::Bytes(b"{\"ok\":true}".to_vec()),
            timestamp: SystemTime::now(),
            peer: None,
        }),
        client_conn: ConnInfo {
            peer: addr,
            sni: Some("api.example.test".into()),
            alpn: Some("http/1.1".into()),
            tls: true,
            established: SystemTime::now(),
        },
        server_conn: None,
        metadata: FlowMeta::default(),
        intercept: InterceptState::Observed,
    })
}

fn ws_flow() -> Flow {
    let addr = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 0));
    let conn = ConnInfo {
        peer: addr,
        sni: Some("ws.example.test".into()),
        alpn: None,
        tls: true,
        established: SystemTime::now(),
    };
    Flow::WebSocket(WsFlow {
        id: FlowId::new(),
        handshake: FlowId::new(),
        messages: vec![
            WsMessage {
                dir: WsDir::ClientToServer,
                opcode: WsOpcode::Text,
                data: b"hello".to_vec(),
                timestamp: SystemTime::now(),
                injected: false,
            },
            WsMessage {
                dir: WsDir::ServerToClient,
                opcode: WsOpcode::Binary,
                data: vec![0u8, 1, 2, 255],
                timestamp: SystemTime::now(),
                injected: true,
            },
        ],
        client_conn: conn.clone(),
        server_conn: Some(conn),
        metadata: FlowMeta::default(),
        intercept: InterceptState::Observed,
    })
}

fn export_bytes(reg: &Registry, store: &MemFlowStore, format: &str) -> Vec<u8> {
    let guard = StdGuard::default();
    let client = CountingClient::default();
    let host = CommandHost::new(store, &client, &guard, None);
    let mut args = BTreeMap::new();
    args.insert("format".to_string(), Value::Str(format.to_string()));
    let out = reg
        .command("flow.export")
        .expect("flow.export registered")
        .invoke(Params::new(args), &host)
        .expect("flow.export ok");
    let Value::Object(out) = out else {
        panic!("flow.export returns an object");
    };
    let Some(Value::Bytes(bytes)) = out.get("bytes") else {
        panic!("flow.export with no path returns bytes");
    };
    bytes.clone()
}

fn import_flows(reg: &Registry, bytes: Vec<u8>, format: &str) -> (MemFlowStore, usize) {
    let guard = StdGuard::default();
    let client = CountingClient::default();
    let fresh = MemFlowStore::new();
    let host = CommandHost::new(&fresh, &client, &guard, None);
    let mut args = BTreeMap::new();
    args.insert("bytes".to_string(), Value::Bytes(bytes));
    args.insert("format".to_string(), Value::Str(format.to_string()));
    let imported = reg
        .command("flow.import")
        .expect("flow.import registered")
        .invoke(Params::new(args), &host)
        .expect("flow.import ok");
    let Value::Object(imported) = imported else {
        panic!("flow.import returns an object");
    };
    let Some(Value::Array(ids)) = imported.get("ids") else {
        panic!("flow.import returns an ids array");
    };
    let n = ids.len();
    assert_eq!(client.sends.load(Ordering::SeqCst), 0, "import is passive");
    (fresh, n)
}

fn req_url(flow: &Flow) -> String {
    let Flow::Http(f) = flow else {
        panic!("expected http flow");
    };
    format!(
        "{}://{}{}",
        f.request.scheme, f.request.authority, f.request.path
    )
}

/// AC-F10.2 — `flow.export {format:"har"}` produces a document that parses as HAR
/// 1.2 whose first entry's `request.url`/`response.status` equal the flow's.
#[test]
fn har_export_is_valid_1_2() {
    let reg = registry();
    let store = MemFlowStore::new();
    let id = store.insert(seeded_flow());
    let flow = store.get(id).unwrap();

    let bytes = export_bytes(&reg, &store, "har");
    let har: Har = serde_json::from_slice(&bytes).expect("export parses as HAR");

    assert_eq!(har.log.version, "1.2", "log.version is the literal 1.2");
    let entry = har.log.entries.first().expect("one entry");
    assert_eq!(
        entry.request.url,
        req_url(&flow),
        "entry url equals the flow's"
    );
    assert_eq!(entry.response.status, 201, "entry status equals the flow's");
}

/// AC-F10.2 — importing that HAR yields a flow with the same URL and status.
#[test]
fn har_import_roundtrips_url_status() {
    let reg = registry();
    let store = MemFlowStore::new();
    let id = store.insert(seeded_flow());
    let original = store.get(id).unwrap();

    let bytes = export_bytes(&reg, &store, "har");
    let (fresh, n) = import_flows(&reg, bytes, "har");
    assert_eq!(n, 1, "one flow imported");

    let imported = fresh
        .list()
        .into_iter()
        .find_map(|id| fresh.get(id))
        .expect("imported flow present");
    assert_eq!(req_url(&imported), req_url(&original), "url round-trips");
    let Flow::Http(f) = &imported else {
        panic!("expected http flow");
    };
    assert_eq!(
        f.response.as_ref().unwrap().status,
        201,
        "status round-trips"
    );
    assert!(
        imported.metadata().marks.iter().any(|m| m == "imported"),
        "imported flow carries the `imported` mark"
    );
    assert!(!imported.metadata().is_replay, "import is not a replay");
}

/// WS messages survive the HAR round-trip via `_webSocketMessages`.
#[test]
fn har_roundtrips_websocket_messages() {
    let reg = registry();
    let store = MemFlowStore::new();
    store.insert(ws_flow());

    let bytes = export_bytes(&reg, &store, "har");
    let (fresh, n) = import_flows(&reg, bytes, "har");
    assert_eq!(n, 1, "one flow imported");

    let imported = fresh
        .list()
        .into_iter()
        .find_map(|id| fresh.get(id))
        .expect("imported flow present");
    let Flow::WebSocket(ws) = &imported else {
        panic!("expected websocket flow");
    };
    assert_eq!(ws.messages.len(), 2, "both ws messages round-trip");
    assert_eq!(ws.messages[0].data, b"hello", "text frame data preserved");
    assert_eq!(ws.messages[0].dir, WsDir::ClientToServer);
    assert_eq!(
        ws.messages[1].data,
        vec![0u8, 1, 2, 255],
        "binary frame preserved"
    );
    assert_eq!(ws.messages[1].dir, WsDir::ServerToClient);
}

/// A genuine mitmproxy 12.2.2 `.flows` blob imports to one flow with the expected
/// URL and status. Import only; the file was written by `mitmproxy.io.FlowWriter`.
#[test]
fn mitmproxy_flows_import() {
    let reg = registry();
    let bytes = include_bytes!("fixtures/sample.flows").to_vec();
    let (fresh, n) = import_flows(&reg, bytes, "mitmproxy");
    assert!(n >= 1, "at least one flow imported, got {n}");

    let imported = fresh
        .list()
        .into_iter()
        .find_map(|id| fresh.get(id))
        .expect("imported flow present");
    assert_eq!(
        req_url(&imported),
        "https://example.test:443/hello?q=1",
        "mitmproxy request url imported"
    );
    let Flow::Http(f) = &imported else {
        panic!("expected http flow");
    };
    assert_eq!(f.response.as_ref().unwrap().status, 200, "status imported");
    assert!(
        imported.metadata().marks.iter().any(|m| m == "imported"),
        "imported flow carries the `imported` mark"
    );
}

/// Panel finding #5: a HAR body tagged `encoding: "base64"` that will not decode is
/// a corrupt document — `flow.import` must fail (not silently drop the body and
/// report success). Nothing is inserted on the failed import.
#[test]
fn har_import_corrupt_base64_body_is_error() {
    let reg = registry();
    let har = r#"{"log":{"version":"1.2","creator":{"name":"t","version":"0"},"entries":[
      {"startedDateTime":"1970-01-01T00:00:00.000Z","time":-1,
       "request":{"method":"GET","url":"https://ex.test/","httpVersion":"HTTP/1.1","headers":[],"headersSize":-1,"bodySize":-1},
       "response":{"status":200,"statusText":"OK","httpVersion":"HTTP/1.1","headers":[],
         "content":{"size":3,"mimeType":"application/octet-stream","text":"!!!not-valid-base64!!!","encoding":"base64"},
         "headersSize":-1,"bodySize":-1},
       "timings":{"send":-1,"wait":-1,"receive":-1}}
    ]}}"#;

    let guard = StdGuard::default();
    let client = CountingClient::default();
    let fresh = MemFlowStore::new();
    let host = CommandHost::new(&fresh, &client, &guard, None);
    let mut args = BTreeMap::new();
    args.insert("bytes".to_string(), Value::Bytes(har.as_bytes().to_vec()));
    args.insert("format".to_string(), Value::Str("har".to_string()));
    let err = reg
        .command("flow.import")
        .expect("flow.import registered")
        .invoke(Params::new(args), &host)
        .expect_err("a corrupt base64 body must fail the import, not be silently dropped");
    assert!(
        err.chain().any(|e| e.to_string().contains("base64")),
        "the error names the base64 decode failure: {err:#}"
    );
    assert_eq!(fresh.count(), 0, "a failed import inserts nothing");
}
